// One-off: add six more Russell Group universities to the United Kingdom,
// checked 2026-10-29: Liverpool, Newcastle, Nottingham, Queen Mary (QMUL),
// York and Queen's University Belfast. Cardiff, the seventh missing member,
// refuses this machine (HTTP 403 on every page), so it is not added.
//
//   node tools/add-uk-russell-2026-10-29.mjs
//
// Same choices as tools/merge-uk-2026-10-29.mjs and tools/fix-uk-2026-10-29.mjs:
// about 30–40 core single-honours programmes per university (the subjects
// Jakub's 19 universities carry), each row from the university's own 2027
// course page (its URL is official_url). The page fields used:
//   Liverpool   "International Baccalaureate" row; "International fees /
//               Full-time place, per year - £…"; "IELTS" row.
//   Newcastle   "International Baccalaureate"; "FT International: £…"; course
//               list from each subject page's data-coursecode (UCAS code).
//   Nottingham  "IB score" / "IB requirements"; the "Fees" pair (UK, then
//               international); "IELTS/English requirements".
//   QMUL        the first programme block: "IB …"; "Overseas fees £…".
//   York        "International Baccalaureate" row; "International and EU
//               fees £…"; "IELTS (Academic)".
//   QUB         "International Baccalaureate Diploma"; the fee table
//               ("Northern Ireland (NI) £4,985", "Republic of Ireland (ROI)",
//               "England, Scotland or Wales (GB)", "EU Other 3 £…": "EU Other
//               students … are charged tuition fees in line with
//               international fees"); "An IELTS score of …".
// Every page states the 2027/28 fees. EU students pay the international fee
// (GOV.UK home fee status rules, see fix-uk); converted at the ECB rate of 29
// October 2026, GBP 0.83578. Newcastle's and QMUL's English levels load from
// another service and are left blank. Liverpool's Medicine page and QUB's
// Medicine, Environmental Management and Nursing pages print no IB offer, so
// those rows have no IB points (unknown, not "none").
//
// Deadlines: UCAS equal-consideration date 13 January 2027; Medicine,
// Dentistry and Veterinary Medicine 15 October 2026 (UCAS), already passed.
// entrance_exam: "yes" for Medicine and Dentistry (UCAT on every page);
// Liverpool Music "either have an interview or a short audition" (waivable);
// York Music "may be called to an interview and audition" (?). Nottingham
// Maths: "Tests such as STEP/MAT/TMUA are not factored into the offer-making
// process" (no).
//
// ib_maths, from each row's IB text: HL2 = HL maths, either course; AAHL =
// "Mathematics Analysis and Approaches at Higher Level"; HL2_AASL = HL either
// course or SL Analysis and Approaches (Nottingham engineering: "SL7 in
// Mathematics: Analysis and Approaches … Applications and Interpretation is
// not accepted at Standard Level"; York CS, Physics, Engineering); ANY = no
// maths course required.
//
// Living costs: the GOV.UK Student visa figure, as for most UK rows
// ("London: £1,529 per month … Outside London: £1,171 per month").
//
// Re-runnable: rows are replaced by id, not appended.

import { readFileSync, writeFileSync } from 'node:fs';
import { parseCsv } from '../js/csv.js';

const DATA = new URL('../data/', import.meta.url);
const TODAY = '2026-10-29';
const GBP_PER_EUR = 0.83578;
const eur = (gbp) => String(Math.round(Number(gbp) / GBP_PER_EUR));
const gbp = (n) => `£${Number(n).toLocaleString('en-GB')}`;
const esc = (v) => { const s = String(v ?? ''); return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const read = (u) => { const [head, ...rows] = parseCsv(readFileSync(u, 'utf8')); return { head, rows: rows.map((r) => Object.fromEntries(head.map((h, i) => [h, r[i] ?? '']))) }; };
const save = (u, head, rows) => writeFileSync(u, [head.join(','), ...rows.map((r) => head.map((h) => esc(r[h])).join(','))].join('\n') + '\n');

const VISA = (london) => ({ living_cost_min: eur(london ? 1529 : 1171), living_cost_source: `national estimate (UK student visa), ${gbp(london ? 1529 : 1171)} a month` });
const UK = { country: 'United Kingdom', application_system: 'UCAS', admission_default: 'UCAS application' };
const UNIS = [
  { ...UK, ...VISA(false), university_id: 'liverpool', name: 'University of Liverpool', city: 'Liverpool' },
  { ...UK, ...VISA(false), university_id: 'newcastle', name: 'Newcastle University', city: 'Newcastle upon Tyne' },
  { ...UK, ...VISA(false), university_id: 'nottingham', name: 'University of Nottingham', city: 'Nottingham' },
  { ...UK, ...VISA(true), university_id: 'qmul', name: 'Queen Mary University of London', city: 'London' },
  { ...UK, ...VISA(false), university_id: 'york', name: 'University of York', city: 'York' },
  { ...UK, ...VISA(false), university_id: 'qub', name: "Queen's University Belfast", city: 'Belfast' },
];

