const PROGS = ROWS.map(([university_id, slug, programme, degree_type, official_url, ib, intl, home, gb, ielts, maths, entrance_exam, early]) => {
  const notes = [early ? 'UCAS deadline 15 October 2026 (Medicine, Dentistry and Veterinary Medicine).' : 'UCAS equal-consideration deadline 13 January 2027.'];
  if (intl) notes.push(feeNote(intl, home));
  if (gb) notes.push(`At Queen's the ${gbp(home)} fee is for students from Northern Ireland and Irish citizens living in Ireland; students from Great Britain pay ${gbp(gb)}.`);
  return {
    programme_id: `${university_id}-${slug}`, university_id, programme, degree_type, official_url, language: 'English',
    subject_area: area(programme), ib_points_min: points(ib), ib_subjects: ib ? `IB Diploma: ${ib}` : '', ib_maths: MATHS[maths],
    admission: 'UCAS application', entrance_exam, other_requirements: entrance_exam === 'yes' ? 'UCAT' : '',
    tuition_eu: intl ? eur(intl) : '', tuition_noneu: intl ? eur(intl) : '', english_requirement: ielts ? `IELTS ${ielts}` : '',
    application_deadline: early ? '2026-10-15' : '2027-01-13', deadline_notes: notes.join(' '),
  };
});

const unis = read(new URL('universities.csv', DATA));
const uniRows = UNIS.map((u) => ({ ...Object.fromEntries(unis.head.map((h) => [h, u[h] ?? ''])), last_verified: TODAY, verified_by: 'AI-DRAFT' }));
const uniIds = new Set(uniRows.map((u) => u.university_id));
save(new URL('universities.csv', DATA), unis.head, [...unis.rows.filter((u) => !uniIds.has(u.university_id)), ...uniRows]);
const progs = read(new URL('programmes.csv', DATA));
const progRows = PROGS.map((p) => ({ ...Object.fromEntries(progs.head.map((h) => [h, p[h] ?? ''])), last_verified: TODAY, verified_by: 'AI-DRAFT' }));
const ids = new Set(progRows.map((p) => p.programme_id));
if (ids.size !== progRows.length) throw new Error('duplicate programme_id');
save(new URL('programmes.csv', DATA), progs.head, [...progs.rows.filter((p) => !ids.has(p.programme_id)), ...progRows]);
console.log(`UK: ${uniRows.length} universities, ${progRows.length} programmes added`);
